from langchain_core.prompts import PromptTemplate
from langchain_openai import ChatOpenAI

class Agent:
    def __init__(self, medical_report=None, role=None, extra_info=None):
        self.medical_report = medical_report
        self.role = role
        self.extra_info = extra_info
        # Initialize the prompt based on role and other info
        self.prompt_template = self.create_prompt_template()
        # Initialize the model
        self.model = ChatOpenAI(temperature=0, model="gpt-5")

    def create_prompt_template(self):
        if self.role == "MultidisciplinaryTeam":
            templates = f"""
                Act like a multidisciplinary team of healthcare professionals.
                You will receive a medical report of a patient visited by a Cardiologist, Psychologist, and Pulmonologist.
                Task: Review the patient's medical report from the Cardiologist, Psychologist, and Pulmonologist, analyze them and come up with a list of 3 possible health issues of the patient.
                Just return a list of bullet points of 3 possible health issues of the patient and for each issue provide the reason.

                Cardiologist Report: {self.extra_info.get('cardiologist_report', '')}
                Psychologist Report: {self.extra_info.get('psychologist_report', '')}
                Pulmonologist Report: {self.extra_info.get('pulmonologist_report', '')}
            """
        else:
            templates = {
                "Cardiologist": """
                    Act like a cardiologist. You will receive a medical report of a patient.
                    Task: Review the patient's cardiac workup, including ECG, blood tests, Holter monitor results, and echocardiogram.
                    Focus: Determine if there are any subtle signs of cardiac issues that could explain the patient’s symptoms. Rule out any underlying heart conditions, such as arrhythmias or structural abnormalities, that might be missed on routine testing.
                    Recommendation: Provide guidance on any further cardiac testing or monitoring needed to ensure there are no hidden heart-related concerns. Suggest potential management strategies if a cardiac issue is identified.
                    Please only return the possible causes of the patient's symptoms and the recommended next steps.
                    Medical Report: {medical_report}
                """,
                "Psychologist": """
                    Act like a psychologist. You will receive a patient's report.
                    Task: Review the patient's report and provide a psychological assessment.
                    Focus: Identify any potential mental health issues, such as anxiety, depression, or trauma, that may be affecting the patient's well-being.
                    Recommendation: Offer guidance on how to address these mental health concerns, including therapy, counseling, or other interventions.
                    Please only return the possible mental health issues and the recommended next steps.
                    Patient's Report: {medical_report}
                """,
                "Pulmonologist": """
                    Act like a pulmonologist. You will receive a patient's report.
                    Task: Review the patient's report and provide a pulmonary assessment.
                    Focus: Identify any potential respiratory issues, such as asthma, COPD, or lung infections, that may be affecting the patient's breathing.
                    Recommendation: Offer guidance on how to address these respiratory concerns, including pulmonary function tests, imaging studies, or other interventions.
                    Please only return the possible respiratory issues and the recommended next steps.
                    Patient's Report: {medical_report}
                """
            }
            templates = templates[self.role]
        return PromptTemplate.from_template(templates)

    def run(self):
        print(f"{self.role} is running...")
        prompt = self.prompt_template.format(medical_report=self.medical_report)
        try:
            response = self.model.invoke(prompt)
            return response.content
        except Exception as e:
            print("Error occurred:", e)
            return None

# Define specialized agent classes
class Cardiologist(Agent):
    def __init__(self, medical_report):
        super().__init__(medical_report, "Cardiologist")

class Psychologist(Agent):
    def __init__(self, medical_report):
        super().__init__(medical_report, "Psychologist")

class Pulmonologist(Agent):
    def __init__(self, medical_report):
        super().__init__(medical_report, "Pulmonologist")

class MultidisciplinaryTeam(Agent):
    def __init__(self, cardiologist_report, psychologist_report, pulmonologist_report):
        extra_info = {
            "cardiologist_report": cardiologist_report,
            "psychologist_report": psychologist_report,
            "pulmonologist_report": pulmonologist_report
        }
        super().__init__(role="MultidisciplinaryTeam", extra_info=extra_info)

import os
import gradio as gr
from typing import Callable
from langchain_openai import ChatOpenAI
from langchain_anthropic import ChatAnthropic
from langchain_google_genai import ChatGoogleGenerativeAI
from langchain_huggingface import HuggingFacePipeline, HuggingFaceEndpoint, ChatHuggingFace
from langchain.schema import HumanMessage, AIMessage
from langchain.chat_models.base import BaseChatModel
from langchain_community.llms import HuggingFaceHub
from langchain_core.messages import HumanMessage, AIMessage
from langchain.chains import LLMChain, ConversationChain
from langchain.prompts import PromptTemplate
from langchain.memory import ConversationBufferMemory

__version__ = "0.0.1"


def get_chat_model(model_name: str, api_key: str | None = None) -> BaseChatModel:
    if model_name.startswith("gpt-"):
        return ChatOpenAI(model_name=model_name, openai_api_key=api_key, streaming=True)
    elif model_name.startswith("claude-"):
        return ChatAnthropic(model=model_name, anthropic_api_key=api_key, streaming=True)
    elif model_name.startswith("gemini-"):
        return ChatGoogleGenerativeAI(model=model_name, google_api_key=api_key, streaming=True)
    elif "/" in model_name:
        if api_key:
            llm = HuggingFaceHub(
                repo_id=model_name,
                task="text-generation",
                model_kwargs={"max_new_tokens": 100, "do_sample": False},
                huggingfacehub_api_token=api_key
            )
            return ChatHuggingFace(llm=llm)
        else:
            return HuggingFacePipeline.from_model_id(
                model_id=model_name,
                task="text-generation",
                pipeline_kwargs={"max_new_tokens": 100, "top_k": 50, "temperature": 0.7},
            )
    else:
        raise ValueError(f"Unsupported model: {model_name}")


def get_chain(model_name: str, api_key: str | None = None) -> ConversationChain:
    llm = get_chat_model(model_name, api_key)
    memory = ConversationBufferMemory(return_messages=True)
    return ConversationChain(llm=llm, memory=memory, verbose=True)


def get_interface_args(pipeline):
    if pipeline == "chat":
        inputs = None
        outputs = None

        def preprocess(message, history):
            return {"input": message}

        postprocess = lambda x: x["response"]
    else:
        raise ValueError(f"Unsupported pipeline type: {pipeline}")

    return inputs, outputs, preprocess, postprocess


def get_pipeline(model_name):
    # For now, assume all models are chat models
    return "chat"


def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str):
    chain = get_chain(model_name, api_key)

    def fn(message, history):
        inputs = preprocess(message, history)
        response = chain(inputs)
        yield postprocess(response)

    return fn


def registry(name: str, token: str | None = None, **kwargs):
    """
    Create a Gradio Interface for a chat model.

    Parameters:
        - name (str): The name of the chat model.
        - token (str, optional): The API key for the model.
    """
    if name.startswith("gpt-"):
        env_var_name = "OPENAI_API_KEY"
    elif name.startswith("claude-"):
        env_var_name = "ANTHROPIC_API_KEY"
    elif name.startswith("gemini-"):
        env_var_name = "GOOGLE_API_KEY"
    elif "/" in name:
        env_var_name = "HUGGINGFACEHUB_API_TOKEN"
    else:
        raise ValueError(f"Unsupported model: {name}")

    api_key = token or os.environ.get(env_var_name)
    if not api_key and "/" not in name:
        raise ValueError(
            f"API key for {name} is not set. "
            f"Please set the {env_var_name} environment variable "
            f"or provide the token parameter."
        )

    pipeline = get_pipeline(name)
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, api_key)

    if pipeline == "chat":
        interface = gr.ChatInterface(fn=fn, **kwargs)
    else:
        # For other pipelines, create a standard Interface (not implemented yet)
        interface = gr.Interface(fn=fn, inputs=inputs, outputs=outputs, **kwargs)

    return interface

import hashlib
import json
import logging
import random
import datetime
import time
from typing import Callable
from typing_extensions import override
from collections import OrderedDict

from langchain_core.language_models import BaseChatModel

from autono.ability.agentic_ability import PREFIX as AGENTIC_ABILITY_PREFIX
from autono.ability.base_ability import BaseAbility
from autono.brain.base_agent import BaseAgent
from autono.brain.hook.before_action_taken import BeforeActionTaken
from autono.brain.hook.after_action_taken import AfterActionTaken
from autono.brain.hook.base_hook import BaseHook
from autono.brain.memory_augment import MemoryAugment
from autono.enum.Personality import Personality
from autono.message.all_done_message import AllDoneMessage
from autono.message.before_action_taken_message import BeforeActionTakenMessage
from autono.message.after_action_taken_message import AfterActionTakenMessage
from autono.prompt import (
    NextMovePrompt,
    ExecutorPrompt,
    IntrospectionPrompt
)

PRUDENT_P = 0.25
PRUDENT_BETA = 1.45
INQUISITIVE_P = 0.05
INQUISITIVE_BETA = 1.25
log = logging.getLogger('autono')


class Agent(BaseAgent, MemoryAugment):
    def __init__(self, abilities: list[Callable],
                 brain: BaseChatModel, name: str = '',
                 personality: Personality = Personality.PRUDENT,
                 request: str = '', memory: OrderedDict | None = None):
        BaseAgent.__init__(self, abilities=abilities, brain=brain, name=name, request=request)
        MemoryAugment.__init__(self, memory=memory)
        self._expected_step = 0
        if personality == Personality.PRUDENT:
            self._p = self.__base_p = PRUDENT_P
            self._beta = PRUDENT_BETA
        elif personality == Personality.INQUISITIVE:
            self._p = self.__base_p = INQUISITIVE_P
            self._beta = INQUISITIVE_BETA

    @property
    def p(self) -> float:
        return self._p

    @property
    def base_p(self) -> float:
        return self.__base_p

    @property
    def beta(self) -> float:
        return self._beta

    @override
    def bring_in_memory(self, memory: OrderedDict):
        self._memory.update(memory)
        log.debug(f'Agent: {self._name}; '
                  f'Memory brought in: {len(memory.keys())};')
        return self

    @override
    def reposition(self):
        BaseAgent.reposition(self)
        self._memory = OrderedDict()
        self._expected_step = 0
        self._p = self.__base_p
        return self

    @override
    def assign(self, request: str):
        BaseAgent.assign(self, request)
        return self.reposition()

    @override
    def reassign(self, request: str):
        return self.assign(request)

    @override
    def relay(self, request: str, request_by_step: str):
        self._request = request
        self._request_by_step = request_by_step
        return self.reposition()

    @override
    def execute(self, args: dict, action: BaseAbility) -> AfterActionTakenMessage:
        return ExecutorPrompt(action=action, args=args).invoke(self.brain)

    @override
    def just_do_it(self, *args, **kwargs) -> AllDoneMessage:
        __after_action_taken_hook: AfterActionTaken | Callable = BaseHook.do_nothing()
        __before_action_taken_hook: BeforeActionTaken | Callable = BaseHook.do_nothing()
        for _arg in args:
            if isinstance(_arg, AfterActionTaken):
                __after_action_taken_hook = _arg
            if isinstance(_arg, BeforeActionTaken):
                __before_action_taken_hook = _arg
        __start_time = time.perf_counter()
        if self._expected_step < 1:
            self.estimate_step()
        log.debug(f'Agent: {self._name}; Expected steps: {self._expected_step}; Request: "{self._request}";')
        stop = False
        while True:
            if self._act_count > self._expected_step:
                stop = self.stop()
                self.penalize()
            next_move = False
            if not stop:
                combined_request = {
                    'raw_request': self._request,
                    'request_by_step': self._request_by_step
                }
                next_move = NextMovePrompt(
                    request=combined_request,
                    abilities=self._abilities,
                    history=self.memory
                ).invoke(self._model)
                if isinstance(next_move, BeforeActionTakenMessage):
                    next_move = __before_action_taken_hook(self, next_move)
                    action, args = next_move.ability, next_move.arguments
                    if action.name.startswith(AGENTIC_ABILITY_PREFIX):
                        args = {
                            'request': self._request,
                            'request_by_step': self._request_by_step,
                            'memory': self.memory,
                            'before_action_taken_hook': __before_action_taken_hook,
                            'after_action_taken_hook': __after_action_taken_hook
                        }
                    __after_execution_msg = self.execute(args=args, action=action)
                    self.memorize(__after_action_taken_hook(self, __after_execution_msg))
                    self._act_count += 1
                    continue
            brief_conclusion, response = IntrospectionPrompt(
                request=self._request,
                history=self.memory,
                self_info=self.introduction
            ).invoke(self._model)
            __time_used = time.perf_counter() - __start_time
            __step_count = self._act_count
            self.reposition()
            log.debug(f'Agent: {self._name}; Conclusion: {brief_conclusion};')
            log.debug(f'Agent: {self._name}; Step count: {__step_count}; Time used: {__time_used} seconds;')
            return AllDoneMessage(
                success=next_move,
                conclusion=brief_conclusion,
                raw_response=response,
                time_used=__time_used,
                step_count=__step_count
            )

    def assign_with_memory(self, request: str, memory: OrderedDict):
        return self.assign(request).bring_in_memory(memory)

    def estimate_step(self):
        if self._request_by_step == '':
            self._expected_step = 0
            return
        self._expected_step = len(self.plan(_log=False))
        return self

    def set_expected_step(self, expected_step: int):
        self._expected_step = expected_step
        return self

    def memorize(self, action_taken: AfterActionTakenMessage):
        if action_taken is None:
            return self
        now = datetime.datetime.now().strftime('%m/%d/%Y %H:%M:%S.%f')
        _tmp_action_taken = action_taken.to_dict()
        if 'summarization' in _tmp_action_taken.keys():
            del _tmp_action_taken['summarization']
        if _tmp_action_taken.get('ability', str()).startswith(AGENTIC_ABILITY_PREFIX):
            if 'arguments' in _tmp_action_taken.keys():
                _tmp_action_taken['arguments'] = 'Ask for a favor.'
        new_memory = {
            "timestamp": now,
            "agent_name": self._name,
            f"message_from_{self._name}": action_taken.summarization,
            f'action_taken_by_{self._name}': _tmp_action_taken
        }
        mem_hash = hashlib.md5(json.dumps(new_memory, ensure_ascii=False).encode()).hexdigest()
        self._memory[f"agent:[{self._name}] at:[{now}] hash:[{mem_hash}]"] = new_memory
        log.debug(f'Agent: {self._name}; Memory size: {len(self._memory.keys())}; Memory update: {action_taken.summarization};')
        return self

    def stop(self) -> bool:
        resample = 3
        log.debug(f'Agent: {self._name}; Termination Probability(p): {self._p}; Penalty Rate(beta): {self._beta};')
        rand_sum = 0.0
        for i in range(resample):
            rand_sum += random.uniform(0, 1)
        rand_avg = rand_sum / resample
        if rand_avg > self._p:
            return False
        return True

    def penalize(self):
        self._p = (self._beta * self._p) % 1.0
        return self

    def set_penalty(self, p: float, beta: float):
        self._p = self.__base_p = p
        self._beta = beta
        return self

    def change_personality(self, personality: Personality):
        if personality == Personality.PRUDENT:
            return self.set_penalty(p=PRUDENT_P, beta=PRUDENT_BETA)
        elif personality == Personality.INQUISITIVE:
            return self.set_penalty(p=INQUISITIVE_P, beta=INQUISITIVE_BETA)
        return self

