```json
{
    "ms": [
        {"a": 1, "b": "b1"},
        {"a": 2, "b": "b2"}
    ],
    "meta": {"key1": "value1", "key2": "value2"}
}
```
"""


def get_format_hint(schema: type[BaseModel]) -> str:
    template = """\
Your answer should be formatted as a JSON instance that conforms to the output schema. The json instance will be used directly to instantiate the Pydantic model.

As an example, given the output schema:
{example_output_schema}

Your answer in this case should be formatted as follows:
{example_output_json}

Here's the real output schema for your reference:
{real_output_schema}

Please provide your answer in the correct json format accordingly. Especially make sure each field will respect the type and constraints defined in the schema.
Pay attention to the enum field in properties, do not generate answer that is not in the enum field if provided.
"""
    return template.format(
        example_output_schema=pydantic_model_repr(ExampleModel),
        example_output_json=example_output_json,
        real_output_schema=pydantic_model_repr(schema),
    )

import json
from langchain_core.messages import BaseMessage, AIMessage, AIMessageChunk, ToolMessage
from rich.console import Console, ConsoleDimensions
from rich.live import Live
from rich.markdown import Markdown
from rich.prompt import Confirm

class OutputHandler:
    def __init__(self, text_only: bool = False, only_last_message: bool = False):
        self.console = Console()
        self.text_only = text_only
        self.only_last_message = only_last_message
        self.last_message = ""
        if self.text_only:
            self.md = ""
        else:
            self.md = "Thinking...\n"
        self._live = None

    def start(self):
        if not self.text_only:
            self._live = Live(
                Markdown(self.md), 
                vertical_overflow="visible", 
                screen=True,
                console=self.console
            )
            self._live.start()

    def update(self, chunk: any):
        self.md = self._parse_chunk(chunk, self.md)
        if(self.only_last_message and self.text_only):
            # when only_last_message, we print in finish()
            return
        if self.text_only:
            self.console.print(self._parse_chunk(chunk), end="")
        else:
            if self.md.startswith("Thinking...") and not self.md.strip("Thinking...").isspace():
                self.md = self.md.strip("Thinking...").strip()
            partial_md = self._truncate_md_to_fit(self.md, self.console.size)
            self._live.update(Markdown(partial_md), refresh=True)

    def update_error(self, error: Exception):
        import traceback
        error = f"Error: {error}\n\nStack trace:\n```\n{traceback.format_exc()}```"
        self.md += error
        if(self.only_last_message):
            self.console.print(error)
            return
        if self.text_only:
            self.console.print_exception()
        else:
            partial_md = self._truncate_md_to_fit(self.md, self.console.size)
            self._live.update(Markdown(partial_md), refresh=True)

    def stop(self):
        if not self.text_only and self._live:
            self._live.stop()

    def confirm_tool_call(self, config: dict, chunk: any) -> bool:
        if not self._is_tool_call_requested(chunk, config):
            return True

        self.stop()
        is_confirmed = self._ask_tool_call_confirmation()
        if not is_confirmed:
            self.md += "# Tool call denied"
            return False

        if not self.text_only:
            self.start()
        return True

    def finish(self):
        self.stop()
        to_print = self.last_message if self.only_last_message else Markdown(self.md)
        if not self.text_only and not self.only_last_message:
            self.console.clear()
            self.console.print(Markdown(self.md))
        if self.only_last_message:
            self.console.print(to_print)

    def _parse_chunk(self, chunk: any, md: str = "") -> str:
        """
        Parse the chunk of agent response.
        It will stream the response as it is received.
        """
        # If this is a message chunk
        if isinstance(chunk, tuple) and chunk[0] == "messages":
            message_chunk = chunk[1][0]  # Get the message content
            if isinstance(message_chunk, AIMessageChunk):
                content = message_chunk.content
                self.last_message += content
                if isinstance(content, str):
                    md += content
                elif isinstance(content, list) and len(content) > 0 and isinstance(content[0], dict) and "text" in content[0]:
                    md += content[0]["text"]
        # If this is a final value
        elif isinstance(chunk, dict) and "messages" in chunk:
            # Print a newline after the complete message
            md += "\n"
            self.last_message = ""
        elif isinstance(chunk, tuple) and chunk[0] == "values":
            message: BaseMessage = chunk[1]['messages'][-1]
            if isinstance(message, AIMessage) and message.tool_calls:
                md += "\n\n### Tool Calls:"
                for tc in message.tool_calls:
                    lines = [
                        f"  {tc.get('name', 'Tool')}",
                    ]
                    if tc.get("error"):
                        lines.append(f"```")
                        lines.append(f"Error: {tc.get('error')}")
                        lines.append("```")

                    lines.append("Args:")
                    lines.append("```")
                    args = tc.get("args")
                    if isinstance(args, str):
                        lines.append(f"{args}")
                    elif isinstance(args, dict):
                        for arg, value in args.items():
                            lines.append(f"{arg}: {value}")
                    lines.append("```\n")
                    md += "\n".join(lines)
                self.last_message = ""
            elif isinstance(message, ToolMessage) and message.status != "success":
                md += "Failed call with error:"
                md += f"\n\n{message.content}"
            md += "\n"
        return md

    def _truncate_md_to_fit(self, md: str, dimensions: ConsoleDimensions) -> str:
        """
        Truncate the markdown to fit the console size, with few line safety margin.
        """
        lines = md.splitlines()
        max_lines = dimensions.height - 3  # Safety margin
        fitted_lines = []
        current_height = 0
        code_block_count = 0

        for line in reversed(lines):
            # Calculate wrapped line height, rounding up for safety
            line_height = 1 + len(line) // dimensions.width

            if current_height + line_height > max_lines:
                # If we're breaking in the middle of code blocks, add closing ```
                if code_block_count % 2 == 1:
                    fitted_lines.insert(0, "```")
                break

            fitted_lines.insert(0, line)
            current_height += line_height

            # Track code block markers
            if line.strip() == "```":
                code_block_count += 1

        return '\n'.join(fitted_lines) if fitted_lines else ''

    def _is_tool_call_requested(self, chunk: any, config: dict) -> bool:
        """
        Check if the chunk contains a tool call request and requires confirmation.
        """
        if isinstance(chunk, tuple) and chunk[0] == "values":
            if len(chunk) > 1 and isinstance(chunk[1], dict) and "messages" in chunk[1]:
                message = chunk[1]['messages'][-1]
                if isinstance(message, AIMessage) and message.tool_calls:
                    for tc in message.tool_calls:
                        if tc.get("name") in config["tools_requires_confirmation"]:
                            return True
        return False

    def _ask_tool_call_confirmation(self) -> bool:
        """
        Ask the user for confirmation to run a tool call.
        """
        self.console.set_alt_screen(True)
        self.console.print(Markdown(self.md))
        self.console.print(f"\n\n")
        is_tool_call_confirmed = Confirm.ask(f"Confirm tool call?", console=self.console)
        self.console.set_alt_screen(False)
        if not is_tool_call_confirmed:
            return False
        return True

from dataclasses import dataclass
from typing import List, Dict, Literal, Optional
import uuid
import json


@dataclass
class Input:
    name: str
    image_type: Optional[Literal["web", "jpeg", "png"]] = None

    def __hash__(self):
        return hash(self.name, self.image_type)


@dataclass
class FilledInput:
    input_variable: Input
    value: str


@dataclass
class TextContent:
    text: str
    type: Literal["text"] = "text"


@dataclass
class ImageContent:
    image_url: dict
    type: Literal["image_url"] = "image_url"


def get_image_content_from_upload(
    image_upload: str, file_type: Literal["jpeg", "png"]
) -> ImageContent:
    return ImageContent({"url": f"data:image/{file_type};base64,{image_upload}"})


Content = TextContent | ImageContent


@dataclass
class Demonstration:
    filled_input_variables: List[FilledInput]
    output: str
    id: str
    reasoning: str = None

    def __init__(
        self,
        filled_input_variables: List[FilledInput],
        output: str,
        id: str = None,
        reasoning: str = None,
    ):
        self.filled_input_variables = filled_input_variables
        self.output = output
        self.id = id or str(uuid.uuid4())
        self.reasoning = reasoning

    def to_content(self) -> List[Content]:
        demo_content: List[Content] = []
        demo_string = ""
        demo_string = "**Input:**\n"
        for filled in self.filled_input_variables:
            demo_string += f"{filled.input_variable.name}:\n"
            input_variable = filled.input_variable
            if input_variable.image_type:
                demo_content.append(TextContent(text=demo_string))
                demo_string = ""
                if input_variable.image_type == "web":
                    demo_content.append(ImageContent(image_url=filled.value))
                else:
                    demo_content.append(
                        get_image_content_from_upload(
                            image_upload=filled.value,
                            file_type=input_variable.image_type,
                        )
                    )
        if self.reasoning is not None:
            demo_string += f"**Reasoning:**\n{self.reasoning}\n"
        else:
            demo_string += "**Reasoning:**\nnot available"
        demo_string += f"**Answer:**\n{self.output}"
        demo_content.append(TextContent(text=demo_string))
        return demo_content

    def __repr__(self):
        """Naive string representation of the demonstration

        NOTE: This is not used for adding demo to the actual user message. check `add_demos_to_prompt` instead.

        Demonstration designer can have their own way to present the demonstration
        especially when the input contains other modalities
        """

        def truncate(text, max_length=200):
            """Truncate text if it exceeds max_length, appending '...' at the end."""
            return text if len(text) <= max_length else text[:max_length] + "..."

        inputs_truncated = {
            filled_input_var.input_variable.name: truncate(filled_input_var.value)
            for filled_input_var in self.filled_input_variables
        }
        input_str = "**Input**\n" + json.dumps(inputs_truncated, indent=4)
        if self.reasoning:
            input_str += f"\n\n**Reasoning**\n{truncate(self.reasoning)}"
        demo_str = f"{input_str}\n\n**Response**\n{truncate(self.output)}"
        return demo_str


@dataclass
class CompletionMessage:
    role: Literal["system", "user", "assistant"]
    content: List[Content]
    name: str = None

    def to_api(self) -> Dict[str, str]:
        msg = {
            "role": self.role,
            "content": [content.__dict__ for content in self.content],
        }
        if self.name:
            msg["name"] = self.name
        return msg

from abc import ABCMeta
from typing import List, Union
from cognify.hub.cogs.common import CogBase, CogLayerLevel, OptionBase, NoChange
from cognify.llm import Model, StructuredModel, litellm_completion
from cognify.llm.model import APICompatibleMessage
from litellm import ModelResponse
import copy

import logging

logger = logging.getLogger(__name__)


class LMReasoning(CogBase):
    level = CogLayerLevel.NODE

    def __init__(
        self,
        options: list[OptionBase],
        name: str = "reasoning",
        default_option: Union[int, str] = 0,
        module_name: str = None,
        inherit: bool = True,
    ):
        return super().__init__(name, options, default_option, module_name, inherit)

    @classmethod
    def from_dict(cls, data: dict):
        name, module_name, default_option, options = (
            data["name"],
            data["module_name"],
            data["default_option"],
            data["options"],
        )
        options = [
            ReasonThenFormat.registry[dat["type"]].from_dict(dat)
            for name, dat in options.items()
        ]
        return cls(
            name=name,
            options=options,
            default_option=default_option,
            module_name=module_name,
        )


class ReasoningOptionMeta(ABCMeta):
    registry: dict[str, type] = {"NoChange": NoChange}

    def __new__(cls, name, bases, attrs):
        new_cls = super().__new__(cls, name, bases, attrs)
        cls.registry[name] = new_cls
        return new_cls


class ReasonThenFormat(OptionBase, metaclass=ReasoningOptionMeta):
    @classmethod
    def direct_apply(cls, lm_module: Model):
        reasoning = cls()
        reasoning.apply(lm_module)
        return reasoning

    def reasoning_step(
        self, model: str, chat_messages: List[APICompatibleMessage], model_kwargs: dict
    ) -> List[ModelResponse]:
        """Produce reasoning steps for the given chat prompt messages"""
        raise NotImplementedError

    def aggregate_reasoning_steps(self, responses: List[ModelResponse]) -> str:
        agg_messages = []
        for response in responses:
            agg_messages.append(f"\n: {response.choices[0].message.content}")
        return "\n".join(agg_messages)

    def forward(
        self, lm_module: Model, messages: List[APICompatibleMessage], model_kwargs: dict
    ) -> List[ModelResponse]:
        """
        If the orignal output has certain format, applying additional reasoning steps will break down
        it into two phases, first one allows free generation along with reasoning steps, and the second
        one will the formatting step
        """

        model: str = model_kwargs.pop("model")
        responses = []

        messages.append(
            {
                "role": "user",
                "content": "Don't give your final response to the instruction directly. We can start with some reasoning first.\n",
            }
        )
        reasoning_step_responses: List[ModelResponse] = self.reasoning_step(
            model, copy.deepcopy(messages), model_kwargs
        )

        responses.extend(reasoning_step_responses)
        rationale = self.aggregate_reasoning_steps(reasoning_step_responses)
        lm_module.rationale = rationale

        messages.append({"role": "assistant", "content": rationale})
        if lm_module.contains_custom_format_instructions():
            messages.append(
                {
                    "role": "user",
                    "content": f"Based on the reasoning, now please only give {lm_module.get_output_label_name()} as your final response, according to the following instructions:\n{lm_module.get_custom_format_instructions_if_any()}",
                }
            )
        else:
            messages.append(
                {
                    "role": "user",
                    "content": f"Based on the reasoning, now please form {lm_module.get_output_label_name()} as your final response.",
                }
            )

        full_messages = [lm_module.system_message.to_api()] + messages
        if isinstance(lm_module, StructuredModel):
            response = litellm_completion(
                model,
                full_messages,
                model_kwargs,
                response_format=lm_module.output_format.schema,
            )
            responses.append(response)
        else:
            response = litellm_completion(model, full_messages, model_kwargs)
            responses.append(response)
        return responses

    def apply(self, lm_module: Model):
        lm_module.reasoning = self
        return lm_module

    @classmethod
    def from_dict(cls, data: dict):
        return cls()


class ZeroShotCoT(ReasonThenFormat):
    def __init__(self):
        super().__init__("ZeroShotCoT")

    def _get_cost_indicator(self):
        return 2.0

    def describe(self):
        desc = """
        - ZeroShotCoT -
        Return step-by-step reasoning for the given chat prompt messages.

        Reasoning Prompt: 
            Let's solve this problem step by step before giving the final response.
        """
        return desc

    def reasoning_step(
        self, model: str, chat_messages: List[APICompatibleMessage], model_kwargs: dict
    ) -> List[ModelResponse]:
        chat_messages.append(
            {
                "role": "user",
                "content": "Let's solve this problem step by step before giving the final response\n",
            }
        )
        response = litellm_completion(model, chat_messages, model_kwargs)
        return [response]


class PlanBefore(ReasonThenFormat):
    def __init__(self):
        super().__init__("PlanBefore")

    def _get_cost_indicator(self):
        return 3.0

    def describe(self):
        desc = """
        - PlanBefore -
        Similar to the planner in the LLMCompiler paper. Plan sub-tasks and synthesize a response for each sub-task as the rationale. Focus more on the runtime query complexity.

        Reasoning Prompt: 
            Let's first break down the task into several simpler sub-tasks that each covers different aspect of the original task. Clearly state each sub-question and provide your response to each one of them.
        """
        return desc

    def reasoning_step(
        self, model: str, chat_messages: List[APICompatibleMessage], model_kwargs: dict
    ) -> List[ModelResponse]:
        # TODO: make this a workflow and parallelize the reasoning steps
        chat_messages.append(
            {
                "role": "user",
                "content": "Let's first break down the task into several simpler sub-tasks that each covers different aspect of the original task. Clearly state each sub-question and provide your response to each one of them.",
            }
        )
        response = litellm_completion(model, chat_messages, model_kwargs)
        return [response]

from litellm import Usage
from openai.types.completion_usage import (
    CompletionUsage,
    PromptTokensDetails,
    CompletionTokensDetails,
)
from dataclasses import dataclass
from typing import List, Optional, Dict


@dataclass
class ResponseMetadata:
    model: str
    cost: float
    usage: Usage


def aggregate_usages(usages: List[Usage]) -> CompletionUsage:
    aggregated_usage = CompletionUsage(
        prompt_tokens=0,
        completion_tokens=0,
        total_tokens=0,
        prompt_tokens_details=PromptTokensDetails(audio_tokens=0, cached_tokens=0),
        completion_tokens_details=CompletionTokensDetails(
            audio_tokens=0, reasoning_tokens=0
        ),
    )
    for usage in usages:
        aggregated_usage.prompt_tokens += usage.get("prompt_tokens", 0)
        aggregated_usage.completion_tokens += usage.get("completion_tokens", 0)
        aggregated_usage.total_tokens += usage.get("total_tokens", 0)

        # token details
        prompt_token_details = usage.get("prompt_tokens_details", None)
        if prompt_token_details:
            aggregated_usage.prompt_tokens_details += prompt_token_details.get(
                "audio_tokens", 0
            )
            aggregated_usage.prompt_tokens_details += prompt_token_details.get(
                "cached_tokens", 0
            )

        completion_token_details = usage.get("completion_tokens_details", None)
        if completion_token_details:
            aggregated_usage.completion_tokens_details += completion_token_details.get(
                "audio_tokens", 0
            )
            aggregated_usage.completion_tokens_details += completion_token_details.get(
                "reasoning_tokens", 0
            )
    return aggregated_usage


